// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp, uint256 blockNumber, uint256 msgValue) public {
        vm.assume(msgValue == 10 ether);
        vm.assume(timestamp > c.pastBlockTime());
        vm.assume(blockNumber % 15 != 0);

        vm.warp(timestamp);
        vm.roll(blockNumber);

        (bool success, ) = address(c).call{value: 10 ether}("");

        assertTrue(success && c.pastBlockTime() == timestamp);
    }
}

